```javascript
function addCopyTodayWakesButton() {
  const todayWakesEl = document.getElementById('today-wakes');
  if (!todayWakesEl) return;
  if (document.getElementById('copy-today-wakes')) return;

  const copyBtn = document.createElement('button');
  copyBtn.id = 'copy-today-wakes';
  copyBtn.type = 'button';
  copyBtn.className = 'copy-button';
  copyBtn.textContent = 'Copy today\'s wakes';
  copyBtn.title = 'Copy the list of today\'s wake times';

  const assignment = document.createElement('span');
  assignment.id = 'copy-today-wakes-announcement';
  assignment.className = 'visually-hidden';
  assignment.setAttribute('role', 'status');
  assignment.setAttribute('aria-live', 'polite');

  todayWakesEl.after(copyBtn, assignment);
}

function copyTodayWakes() {
  const container = document.getElementById('today-wakes');
  const copyBtn = document.getElementById('copy-today-wakes');
  if (!container || !copyBtn) return;
  const assignment = document.getElementById('copy-today-wakes-announcement');
  const originalLabel = copyBtn.textContent;

  const fallback = (text) => {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta);
  };

  const announceCopy = () => {
    copyBtn.textContent = 'Copied!';
    if (assignment) assignment.textContent = 'Copied!';
    setTimeout(() => {
      copyBtn.textContent = originalLabel;
      if (assignment) assignment.textContent = '';
    }, 1500);
  };

  const items = Array.from(container.querySelectorAll('li'));
  const text = items.map(item => item.textContent.trim()).join('\n');

  if (!text) {
    copyBtn.textContent = 'Unavailable';
    if (assignment) assignment.textContent = 'No wakes to copy.';
    setTimeout(() => {
      copyBtn.textContent = originalLabel;
      if (assignment) assignment.textContent = '';
    }, 1500);
    return;
  }

  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(text).then(announceCopy).catch(() => {
      fallback(text);
      announceCopy();
    });
  } else {
    fallback(text);
    announceCopy();
  }
}
```

