function addShareButton() {
  if (document.getElementById('share-btn')) return;
  const btn = document.createElement('button');
  btn.id = 'share-btn';
  btn.type = 'button';
  btn.className = 'copy-button';
  btn.textContent = 'Share page';
  btn.title = 'Share or copy this page URL';

  const assignment = document.createElement('span');
  assignment.id = 'share-announcement';
  assignment.className = 'visually-hidden';
  assignment.setAttribute('role', 'status');
  assignment.setAttribute('aria-live', 'polite');

  document.body.appendChild(btn, assignment);
}

function sharePage() {
  const url = window.location.href;
  const copyBtn = document.getElementById('share-btn');
  const assignment = document.getElementById('share-announcement');
  const originalLabel = copyBtn ? copyBtn.textContent : '';

  const fallback = (text) => {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta);
  };

  const announceCopy = () => {
    if (copyBtn) copyBtn.textContent = 'Copied!';
    if (assignment) assignment.textContent = 'Copied!';
    setTimeout(() => {
      if (copyBtn) copyBtn.textContent = originalLabel;
      if (assignment) assignment.textContent = '';
    }, 1500);
  };

  if (navigator.share) {
    navigator.share({ url }).catch(() => {
      fallback(url);
      announceCopy();
    });
  } else if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(url).then(announceCopy).catch(() => {
      fallback(url);
      announceCopy();
    });
  } else {
    fallback(url);
    announceCopy();
  }
}
```

